public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputStr = scanner.next();
        char[] strInput = inputStr.toCharArray();
        int length = strInput.length;

        for (int idx = 0; idx < length; ++idx) {
            if (idx != 0 && idx != (length - 3)) {
                if (strInput[idx] == 'd') {
                    int tempIdx = idx + 1;
                    if (tempIdx < length && strInput[tempIdx] == 'o') {
                        tempIdx++;
                        if (tempIdx < length && strInput[tempIdx] == 't') {
                            strInput[idx] = '.';
                        }
                    }
                }
            }
        }

        int at_found = 0;
        for (int idx = 0; idx < length; ++idx) {
            if (idx != 0 && idx != (length - 2)) {
                if (strInput[idx] == 'a') {
                    int tempIdx = idx + 1;
                    if (tempIdx < length && strInput[tempIdx] == 't') {
                        strInput[idx] = '@';
                        at_found = 1;
                        break;
                    }
                }
            }
            if (at_found == 1) break;
        }

        StringBuilder output = new StringBuilder();
        int i = 0;
        while (i < length) {
